class Solution {
public:
    string toGoatLatin(string sentence) {
        string result;
        int n = sentence.size();
        int i = 0;
        int wordIndex = 0;
        auto isVowel = [](char c) -> bool {
            char d = (c >= 'A' && c <= 'Z') ? (c - 'A' + 'a') : c;
            return d == 'a' || d == 'e' || d == 'i' || d == 'o' || d == 'u';
        };
        while (i < n) {
            int start = i;
            while (i < n && sentence[i] != ' ') i++;
            int end = i;
            wordIndex++;
            if (isVowel(sentence[start])) {
                for (int j = start; j < end; j++) result += sentence[j];
            } else {
                for (int j = start + 1; j < end; j++) result += sentence[j];
                result += sentence[start];
            }
            result += 'm';
            result += 'a';
            for (int k = 0; k < wordIndex; k++) result += 'a';
            if (i < n) {
                result += ' ';
                i++;
            }
        }
        return result;
    }
};
